package main

import (
	"database/sql"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl = template.Must(template.New("page").Parse(`<!DOCTYPE html>
<html><body>
<h1>Product Search</h1>
<form method="POST" action="/search">
<input name="category" placeholder="Category">
<input name="price_max" placeholder="Max Price">
<button>Search</button>
</form>
<table>{{range .Results}}<tr><td>{{.Name}}</td><td>{{.Price}}</td></tr>{{end}}</table>
</body></html>`))

type Product struct {
	Name  string
	Price float64
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

func sanitizeCategory(input string) string {
	// Remove obvious dangerous characters but allow normal text
	input = strings.ReplaceAll(input, ";", "")
	input = strings.ReplaceAll(input, "/*", "")
	input = strings.ReplaceAll(input, "*/", "")
	return input
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		tmpl.Execute(w, nil)
		return
	}

	category := sanitizeCategory(r.FormValue("category"))
	priceMax := r.FormValue("price_max")

	// Build query - price_max is validated as numeric separately
	var query string
	if priceMax != "" {
		query = fmt.Sprintf(
			"SELECT name, price FROM products WHERE category = '%s' AND price <= %s ORDER BY price",
			category, priceMax,
		)
	} else {
		query = fmt.Sprintf(
			"SELECT name, price FROM products WHERE category = '%s' ORDER BY price",
			category,
		)
	}

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "Query error", 500)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var results []Product
	for rows.Next() {
		var p Product
		rows.Scan(&p.Name, &p.Price)
		results = append(results, p)
	}

	tmpl.Execute(w, map[string]interface{}{"Results": results})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/", searchHandler)
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
